def run(context):
    if 'ranked_candidates' not in context:
        return {'error': 'ranked_candidates key missing'}
    ranked_candidates = context['ranked_candidates']
    position_sizes = {}
    total_weight = 100
    num_candidates = len(ranked_candidates)
    if num_candidates == 0:
        return {'error': 'No ranked candidates available'}
    for candidate in ranked_candidates:
        position_sizes[candidate['symbol']] = total_weight / num_candidates
    return {'position_sizes': position_sizes}

def run(context):
    index_returns = context['index_returns']
    stage_changes = context['stage_distribution_change']
    risks = identify_risks(index_returns, stage_changes)
    return {'risks': risks}

def identify_risks(index_returns, stage_changes):
    risks = []
    for index in index_returns:
        risk_level = 'low' if index['change_pct'] > 0 else 'high'
        risks.append(risk_level)
    return risks

def run(context):
    vcp_picks_data = context.get('vcp_picks_data', [])
    vcp_picks_data = sorted(vcp_picks_data, key=lambda x: (x.get('vcp_score', 0), x.get('enhanced_fund_score', 0)), reverse=True)
    ranked_candidates = [{'symbol': v['symbol'], 'score': v['vcp_score']} for v in vcp_picks_data if v.get('vcp_score') and v.get('enhanced_fund_score')]
    return {'ranked_candidates': ranked_candidates}

def run(context):
    missing_data = []
    for stock in context['report.enhanced_filtered_stocks']:
        if not all([stock.get('current_price'), stock.get('open_price'), stock.get('high_price')]):
            missing_data.append(stock['symbol'])
    return {
        'missing_data': missing_data,
        'verification': len(missing_data) == 0
    }

